# Pure Python: ছোট Schema ও Prediction Contract Validator (কোনো pandas/numpy ছাড়াই!)
def validate_record(row):
    # ১) Customer ID অবশ্যই string থাকতে হবে, যেন শুরুর '00' মুছে না যায়
    cid = row.get("customer_id")
    if not isinstance(cid, str) or len(cid) == 0:
        raise ValueError("customer_id must be a non-empty string")

    # ২) age হতে হবে সংখ্যা এবং ঘোষিত সীমা 0..120-এর ভেতরে
    age = row.get("age")
    if not isinstance(age, (int, float)) or isinstance(age, bool):
        raise ValueError("age must be numeric")
    if not (0 <= age <= 120):
        raise ValueError("age outside the declared contract (0..120)")

    # ৩) সময়ের শর্ত: t_event <= t_pred < t_label (ভবিষ্যতের তথ্য নিষিদ্ধ!)
    if not (row["t_event"] <= row["t_pred"] < row["t_label"]):
        raise ValueError("temporal contract violated: future information leaked!")

    # ৪) Target Label কেবল অনুমোদিত ক্লাসের একটি হতে হবে
    if row.get("income") not in ("<=50K", ">50K"):
        raise ValueError("unknown target label")
    return True


sample_rows = [
    {"customer_id": "00123", "age": 39, "t_event": 10, "t_pred": 12, "t_label": 42, "income": "<=50K"},
    {"customer_id": "00456", "age": 360, "t_event": 10, "t_pred": 12, "t_label": 42, "income": ">50K"},
    {"customer_id": "00789", "age": 28, "t_event": 15, "t_pred": 12, "t_label": 42, "income": "<=50K"},
]

for idx in range(len(sample_rows)):
    rec = sample_rows[idx]
    try:
        ok = validate_record(rec)
        print(f"Row {idx} (ID={rec['customer_id']}): PASS ({ok})")
    except ValueError as err:
        print(f"Row {idx} (ID={rec['customer_id']}): REJECT -> {err}")

import math

# Pure Python: স্ক্র্যাচ থেকে নিরাপদ ও অপরিবর্তনীয় (Frozen) MedianImputer
class MedianImputer:
    def fit(self, values):
        seen = []
        for v in values:
            if v is not None:
                if not isinstance(v, (int, float)) or not math.isfinite(v):
                    raise ValueError("All observed training values must be finite numbers")
                seen.append(float(v))

        if len(seen) == 0:
            raise ValueError("Cannot fit MedianImputer on an all-missing column")

        seen.sort()
        n = len(seen)
        mid = n // 2
        if n % 2 == 1:
            self.fill_ = seen[mid]
        else:
            self.fill_ = (seen[mid - 1] + seen[mid]) / 2.0
        return self

    def transform(self, values):
        if not hasattr(self, "fill_"):
            raise RuntimeError("Call fit() before transform()")
        out = []
        for v in values:
            if v is None:
                out.append(self.fill_)
            else:
                out.append(float(v))
        return out


train_col = [10, 20, None, 90]
holdout_col = [None, 140]

imputer = MedianImputer().fit(train_col)
imputed_train = imputer.transform(train_col)
imputed_holdout = imputer.transform(holdout_col)

print("Learned Frozen Median:", imputer.fill_)
print("Imputed Train:", imputed_train)
print("Imputed Holdout:", imputed_holdout)
print("Original holdout unchanged:", holdout_col)

