from statistics import median
from math import isfinite


def fit_median(values):
    observed = [v for v in values if v is not None]
    if not observed or not all(isfinite(v) for v in observed):
        raise ValueError("Finite observed training values required")
    return median(observed)


def transform(values, fill):
    return [fill if v is None else v for v in values]


fill = fit_median([10, 20, None, 90])
assert transform([None, 140], fill) == [20, 140]
print(fill)  # 20

from math import sin, cos, pi, hypot


def encode(hour):
    phase = 2 * pi * hour / 24
    return sin(phase), cos(phase)


a, b = encode(23), encode(0)
print(hypot(a[0] - b[0], a[1] - b[1]))  # about 0.261052
